grid = [[8]*8 for _ in range(30)]
marks = [(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
for r,c in marks: grid[r][c]=7
# Connect all collinear marker sets using color 3, preserving markers.
for r in range(30):
    cs=[c for rr,c in marks if rr==r]
    if len(cs)>=2:
        for c in range(min(cs),max(cs)+1):
            if grid[r][c]!=7: grid[r][c]=3
for c in range(8):
    rs=[r for r,cc in marks if cc==c]
    if len(rs)>=2:
        for r in range(min(rs),max(rs)+1):
            if grid[r][c]!=7: grid[r][c]=3
assert len(grid)==30 and all(len(row)==8 and set(row)<=set(range(10)) for row in grid)
import json
print(json.dumps(grid,separators=(',',':')))
print('row-count',len(grid),'row-lengths',sorted(set(map(len,grid))))
